package com.farika.soundflow;
import android.app.*;import android.widget.*;import android.view.*;import java.util.*;
final class EqualizerPanel {
 private static AudioEqualizer eq(Activity a){PlaybackService s=PlaybackService.instance;return s==null?new AudioEqualizer(a):s.equalizer();}
 static View create(Activity a){LinearLayout card=SoundFlowUi.card(a);Switch toggle=new Switch(a);toggle.setText("Эквалайзер");toggle.setTextColor(SoundFlowUi.TEXT);toggle.setTextSize(18);toggle.setChecked(eq(a).enabled());card.addView(toggle);SoundFlowUi.gap(card,8);card.addView(SoundFlowUi.text(a,"−12…+12 дБ · пять полос. Пресеты можно настроить вручную.",14,SoundFlowUi.MUTED,false));
 Spinner presets=new Spinner(a);ArrayAdapter<String> options=new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,presetNames());presets.setAdapter(options);presets.setContentDescription("Пресет эквалайзера");card.addView(presets,new LinearLayout.LayoutParams(-1,SoundFlowUi.dp(a,48)));
 LinearLayout columns=new LinearLayout(a);final ArrayList<VerticalFader> faders=new ArrayList<>();final ArrayList<TextView> values=new ArrayList<>();int[] frequencies=eq(a).frequencies();
 for(int frequency:frequencies){LinearLayout band=SoundFlowUi.column(a);band.setGravity(Gravity.CENTER);String label=frequency>=1000000?String.format(Locale.US,"%.1fk",frequency/1000000f):""+(frequency/1000);TextView value=SoundFlowUi.text(a,String.format(Locale.US,"%+.0f",eq(a).gain(frequency)/100f),13,SoundFlowUi.MUTED,false);values.add(value);band.addView(value);VerticalFader fader=new VerticalFader(a,label+" Гц",eq(a).gain(frequency),gain->{eq(a).gain(frequency,gain);value.setText(String.format(Locale.US,"%+.0f",gain/100f));a.getSharedPreferences("equalizer",0).edit().putInt("preset",-1).apply();presets.setSelection(0);});fader.setEnabled(toggle.isChecked());faders.add(fader);band.addView(fader,new LinearLayout.LayoutParams(-1,SoundFlowUi.dp(a,210)));band.addView(SoundFlowUi.text(a,label,13,SoundFlowUi.TEXT,true));columns.addView(band,new LinearLayout.LayoutParams(0,-2,1));}card.addView(columns);
 int initial=a.getSharedPreferences("equalizer",0).getInt("preset",-1);presets.setSelection(Math.max(0,initial+1));presets.post(()->presets.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int index,long id){if(index==0||a.getSharedPreferences("equalizer",0).getInt("preset",-1)==index-1)return;int[] gains=EqPresets.gains(index-1);AudioEqualizer e=eq(a);e.enable(true);toggle.setChecked(true);for(int i=0;i<gains.length;i++){e.gain(frequencies[i],gains[i]);faders.get(i).gain(gains[i]);values.get(i).setText(String.format(Locale.US,"%+.0f",gains[i]/100f));}a.getSharedPreferences("equalizer",0).edit().putInt("preset",index-1).apply();}}));
 toggle.setOnCheckedChangeListener((v,on)->{eq(a).enable(on);for(VerticalFader f:faders)f.setEnabled(on);});SoundFlowUi.gap(card,8);card.addView(SoundFlowUi.button(a,"Сбросить",false,()->{eq(a).reset();for(int i=0;i<faders.size();i++){faders.get(i).gain(0);values.get(i).setText("+0");}a.getSharedPreferences("equalizer",0).edit().putInt("preset",0).apply();presets.setSelection(1);}));return card;
 }
 private static String[] presetNames(){String[] names=new String[EqPresets.NAMES.length+1];names[0]="Свой";System.arraycopy(EqPresets.NAMES,0,names,1,EqPresets.NAMES.length);return names;}
 static void show(Activity a){new AlertDialog.Builder(a).setTitle("Эквалайзер").setView(create(a)).setPositiveButton("Готово",null).show();}
}
